<script setup lang="ts">
// 富化产出分型只读渲染卡片：摘要 / 标签 / 难度 / 质量 / 建议。
// 审核卡片预览与「题目产出详情」抽屉共用，保证两处展示口径一致。
import { gradeName, visibilityText } from "./enrich-common";

const props = defineProps<{
  taskType: string;
  payload: Record<string, unknown>;
  // 可选元信息行（来源/审核状态/置信度等），传入才显示
  meta?: {
    visibility?: string;
    source?: string;
    golden?: boolean;
    review_status?: string;
    confidence?: number;
    model?: string;
    insert_time?: string;
  };
  showEvidence?: boolean; // 难度/质量证据默认折叠，置 true 展开
}>();

// 模板里放宽类型，便于直接取字段
const p = (): any => props.payload ?? {};

const severityTheme = (s: string): string =>
  s === "block" ? "danger" : s === "warn" ? "warning" : "default";

// 证据维度键名中文化
const evidenceLabel: Record<string, string> = {
  thinking: "思维难度",
  algorithm: "算法要求",
  implementation: "实现难度",
  pitfalls: "陷阱密度",
  completeness: "题面完整性",
  examples: "样例充分性",
  judge_config: "判题配置",
  data_strength: "数据强度",
};

// 建议维度键名中文化
const dimensionText: Record<string, string> = {
  constraints: "数据范围/约束",
  io: "输入输出",
  examples: "样例",
  judge_config: "判题配置",
  data: "测试数据",
  statement: "题面表述",
};

// 质量各维度评分来源中文化
const sourceDesc: Record<string, string> = {
  rule: "规则",
  model: "模型",
  "rule+model": "规则+模型",
  "data:submit_distribution": "提交分布",
  "data:insufficient": "数据不足",
};
</script>

<template>
  <div class="annotation-card">
    <!-- 元信息行 -->
    <div v-if="meta" class="ac-meta">
      <t-space size="small" break-line>
        <t-tag v-if="meta.visibility" variant="outline" size="small">
          {{ visibilityText[meta.visibility] || meta.visibility }}
        </t-tag>
        <t-tag v-if="meta.source === 'human'" theme="default" variant="dark" size="small">人工定稿</t-tag>
        <t-tag v-else-if="meta.source === 'ai'" variant="light" size="small">AI</t-tag>
        <t-tag v-if="meta.golden" theme="warning" variant="dark" size="small">黄金集</t-tag>
        <t-tag
          v-if="meta.review_status === 'pending'"
          theme="warning"
          variant="light"
          size="small"
        >
          待审核
        </t-tag>
        <t-tag
          v-else-if="meta.review_status === 'rejected'"
          theme="danger"
          variant="light"
          size="small"
        >
          已驳回
        </t-tag>
        <span v-if="meta.confidence != null" class="ac-meta-text">
          置信 {{ Math.round(meta.confidence * 100) }}%
        </span>
        <span v-if="meta.model" class="ac-meta-text">{{ meta.model }}</span>
      </t-space>
    </div>

    <!-- 摘要 -->
    <template v-if="taskType === 'summary'">
      <div class="ac-line"><span class="ac-label">题意：</span>{{ p().oneliner }}</div>
      <div class="ac-line"><span class="ac-label">输入输出：</span>{{ p().io_points }}</div>
      <div class="ac-line"><span class="ac-label">规模：</span>{{ p().scale }}</div>
    </template>

    <!-- 标签 -->
    <template v-else-if="taskType === 'tags'">
      <t-space size="small" break-line>
        <t-tag v-for="t in p().canonical || []" :key="`c${t}`" theme="success" variant="light">
          {{ t }}
        </t-tag>
        <t-tag v-for="t in p().raw || []" :key="`r${t}`" variant="outline">{{ t }}</t-tag>
        <span v-if="!(p().canonical || []).length && !(p().raw || []).length" class="ac-meta-text">
          无标签
        </span>
      </t-space>
    </template>

    <!-- 难度 -->
    <template v-else-if="taskType === 'difficulty'">
      <div class="ac-line">
        <t-tag theme="primary" variant="dark">{{ gradeName(p().overall) }}</t-tag>
        <span class="ac-dims">
          思维 {{ p().thinking }} · 算法 {{ p().algorithm }} · 实现 {{ p().implementation }} · 陷阱
          {{ p().pitfalls }}
        </span>
      </div>
      <div v-if="showEvidence && p().evidence" class="ac-evidence">
        <div v-for="(v, k) in p().evidence" :key="k" v-show="v" class="ac-evidence-row">
          <span class="ac-label">{{ evidenceLabel[String(k)] || k }}：</span>{{ v }}
        </div>
      </div>
    </template>

    <!-- 质量 -->
    <template v-else-if="taskType === 'quality'">
      <div class="ac-line">
        <t-tag theme="primary" variant="dark">{{ p().overall }} 分</t-tag>
        <span class="ac-dims">
          完整性 {{ p().completeness }} · 样例 {{ p().examples }} · 判题配置
          {{ p().judge_config }} · 数据强度 {{ p().data_strength }}
        </span>
      </div>
      <!-- 各维度评分来源（规则/模型/提交数据）：让评分有据可查 -->
      <div v-if="p().sources" class="ac-sources">
        <span
          v-for="(src, k) in p().sources"
          :key="k"
          class="ac-source-item"
          :title="sourceDesc[String(src)] || String(src)"
        >
          {{ evidenceLabel[String(k)] || k }}：{{ sourceDesc[String(src)] || src }}
        </span>
      </div>
      <div v-if="showEvidence && p().evidence" class="ac-evidence">
        <div v-for="(v, k) in p().evidence" :key="k" v-show="v" class="ac-evidence-row">
          <span class="ac-label">{{ evidenceLabel[String(k)] || k }}：</span>{{ v }}
        </div>
      </div>
    </template>

    <!-- 改进建议 -->
    <template v-else-if="taskType === 'suggestion'">
      <div v-for="(s, i) in p().items || []" :key="i" class="ac-sugg">
        <div class="ac-sugg-head">
          <t-tag size="small" theme="primary" variant="outline">{{ dimensionText[String(s.dimension)] || s.dimension }}</t-tag>
          <t-tag size="small" :theme="severityTheme(s.severity)" variant="light">
            {{ s.severity }}
          </t-tag>
        </div>
        <span class="ac-sugg-text">{{ s.suggestion }}</span>
        <div v-if="s.evidence" class="ac-sugg-evidence" :title="s.evidence">{{ s.evidence }}</div>
      </div>
      <div v-if="!(p().items || []).length" class="ac-meta-text">无改进建议</div>
    </template>

    <div v-else class="ac-meta-text">未知产出类型：{{ taskType }}</div>
  </div>
</template>

