  border-bottom: none;
}

.ac-sugg-head {
  display: flex;
  gap: 6px;
  align-items: center;
}

.ac-sugg-text {
  flex: 1;
}

.ac-sugg-evidence {
  font-size: 12px;
  color: var(--td-text-color-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 质量维度评分来源 */
.ac-sources {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  margin-top: 2px;
}

.ac-source-item {
  font-size: 12px;
